-- ============================================================================
-- DATABASE SCRIPT: shopbangiay
-- Du an: He thong ban giay Sneaker F6S Store
-- Script tao moi toan bo database, schema va du lieu khoi tao chuan.
-- Chay bang SQL Server Management Studio (SSMS) hoac sqlcmd.
-- ============================================================================
USE master;
GO
IF DB_ID('shopbangiay') IS NOT NULL
BEGIN
    ALTER DATABASE shopbangiay SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE shopbangiay;
END;
GO
CREATE DATABASE shopbangiay;
GO
USE shopbangiay;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
-- ------------------------------------------------------------
-- Table: roles
-- ------------------------------------------------------------
CREATE TABLE [roles] (
    [id] int IDENTITY(1,1) NOT NULL,
    [name] varchar(50) NOT NULL,
    CONSTRAINT [PK_roles] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: users
-- ------------------------------------------------------------
CREATE TABLE [users] (
    [id] int IDENTITY(1,1) NOT NULL,
    [username] varchar(50) NOT NULL,
    [password] varchar(255) NOT NULL,
    [role_id] int NOT NULL,
    [status] bit DEFAULT ((1)) NULL,
    [full_name] nvarchar(255) NULL,
    [email] nvarchar(255) NULL,
    [phone] nvarchar(255) NULL,
    [created_at] datetime2 NULL,
    [must_change_password] bit DEFAULT ((0)) NOT NULL,
    [credential_mail_failed] bit DEFAULT ((0)) NOT NULL,
    [credential_mail_window] datetime2 NULL,
    [credential_mail_count] int DEFAULT ((0)) NOT NULL,
    [credential_mail_pending_until] datetime2 NULL,
    CONSTRAINT [PK_users] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: customers
-- ------------------------------------------------------------
CREATE TABLE [customers] (
    [id] int IDENTITY(1,1) NOT NULL,
    [customer_code] varchar(20) NULL,
    [full_name] nvarchar(100) NOT NULL,
    [phone] nvarchar(20) NULL,
    [email] nvarchar(100) NULL,
    [address] nvarchar(255) NULL,
    [created_at] datetime DEFAULT (getdate()) NULL,
    [status] bit DEFAULT ((1)) NULL,
    [user_id] int NULL,
    [so_cccd] varchar(12) NULL,
    [ngay_sinh] date NULL,
    [gioi_tinh] nvarchar(10) NULL,
    [danh_gia_cua_so] datetime2 NULL,
    [danh_gia_so_lan] int DEFAULT ((0)) NOT NULL,
    CONSTRAINT [PK_customers] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: employees
-- ------------------------------------------------------------
CREATE TABLE [employees] (
    [id] int IDENTITY(1,1) NOT NULL,
    [employee_code] varchar(20) NULL,
    [full_name] nvarchar(255) NOT NULL,
    [phone] nvarchar(20) NULL,
    [email] nvarchar(100) NULL,
    [address] nvarchar(255) NULL,
    [position] nvarchar(100) NULL,
    [user_id] int NOT NULL,
    [status] bit DEFAULT ((1)) NULL,
    [so_cccd] varchar(12) NULL,
    [ngay_sinh] date NULL,
    [gioi_tinh] nvarchar(10) NULL,
    CONSTRAINT [PK_employees] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: categories
-- ------------------------------------------------------------
CREATE TABLE [categories] (
    [id] int IDENTITY(1,1) NOT NULL,
    [name] nvarchar(100) NOT NULL,
    [status] bit DEFAULT ((1)) NULL,
    [ma] varchar(20) DEFAULT (concat('TH',format(NEXT VALUE FOR [dbo].[categories_ma_seq],'000'))) NOT NULL,
    CONSTRAINT [PK_categories] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: chat_lieu
-- ------------------------------------------------------------
CREATE TABLE [chat_lieu] (
    [id] int IDENTITY(1,1) NOT NULL,
    [ten] nvarchar(100) NOT NULL,
    [trang_thai] bit DEFAULT ((1)) NOT NULL,
    [ma] varchar(20) DEFAULT (concat('CL',format(NEXT VALUE FOR [dbo].[chat_lieu_ma_seq],'000'))) NOT NULL,
    CONSTRAINT [PK_chat_lieu] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: de_giay
-- ------------------------------------------------------------
CREATE TABLE [de_giay] (
    [id] int IDENTITY(1,1) NOT NULL,
    [ten] nvarchar(100) NOT NULL,
    [trang_thai] bit DEFAULT ((1)) NOT NULL,
    [ma] varchar(20) DEFAULT (concat('DG',format(NEXT VALUE FOR [dbo].[de_giay_ma_seq],'000'))) NOT NULL,
    CONSTRAINT [PK_de_giay] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: mau_sac
-- ------------------------------------------------------------
CREATE TABLE [mau_sac] (
    [id] int IDENTITY(1,1) NOT NULL,
    [ten] nvarchar(100) NOT NULL,
    [ma_mau] varchar(7) NULL,
    [trang_thai] bit DEFAULT ((1)) NOT NULL,
    [ma] varchar(20) DEFAULT (concat('MS',format(NEXT VALUE FOR [dbo].[mau_sac_ma_seq],'000'))) NOT NULL,
    CONSTRAINT [PK_mau_sac] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: sizes
-- ------------------------------------------------------------
CREATE TABLE [sizes] (
    [id] int IDENTITY(1,1) NOT NULL,
    [size_value] nvarchar(10) NOT NULL,
    [ma] varchar(20) DEFAULT (concat('KC',format(NEXT VALUE FOR [dbo].[sizes_ma_seq],'000'))) NOT NULL,
    [trang_thai] bit DEFAULT ((1)) NOT NULL,
    CONSTRAINT [PK_sizes] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: products
-- ------------------------------------------------------------
CREATE TABLE [products] (
    [id] int IDENTITY(1,1) NOT NULL,
    [code] varchar(50) NULL,
    [name] nvarchar(255) NOT NULL,
    [description] nvarchar(MAX) NULL,
    [category_id] int NULL,
    [image_url] nvarchar(500) NULL,
    [status] bit DEFAULT ((1)) NULL,
    [de_giay_id] int NULL,
    CONSTRAINT [PK_products] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: product_variants
-- ------------------------------------------------------------
CREATE TABLE [product_variants] (
    [id] int IDENTITY(1,1) NOT NULL,
    [product_id] int NULL,
    [size_id] int NULL,
    [price] decimal(18,2) NOT NULL,
    [quantity] int DEFAULT ((0)) NOT NULL,
    [status] bit DEFAULT ((1)) NULL,
    [chat_lieu_id] int NOT NULL,
    [mau_sac_id] int NOT NULL,
    [de_giay_id] int NOT NULL,
    [ma] varchar(20) DEFAULT (concat('BT',format(NEXT VALUE FOR [dbo].[product_variants_ma_seq],'0000'))) NOT NULL,
    CONSTRAINT [PK_product_variants] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: product_images
-- ------------------------------------------------------------
CREATE TABLE [product_images] (
    [id] bigint IDENTITY(1,1) NOT NULL,
    [product_id] int NOT NULL,
    [duong_dan] nvarchar(2048) NOT NULL,
    [thu_tu] int NOT NULL,
    [la_anh_chinh] bit DEFAULT ((0)) NOT NULL,
    CONSTRAINT [PK_product_images] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: inventory_logs
-- ------------------------------------------------------------
CREATE TABLE [inventory_logs] (
    [id] bigint IDENTITY(1,1) NOT NULL,
    [variant_id] int NOT NULL,
    [quantity_change] int NOT NULL,
    [quantity_before] int NOT NULL,
    [quantity_after] int NOT NULL,
    [reason] nvarchar(500) NOT NULL,
    [actor] nvarchar(255) NOT NULL,
    [created_at] datetime2 DEFAULT (sysdatetime()) NOT NULL,
    CONSTRAINT [PK_inventory_logs] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: tinh_thanh
-- ------------------------------------------------------------
CREATE TABLE [tinh_thanh] (
    [id] int IDENTITY(1,1) NOT NULL,
