    [end_date] datetime NOT NULL,
    [status] bit DEFAULT ((1)) NULL,
    [ma] varchar(20) DEFAULT (concat('KM',format(NEXT VALUE FOR [dbo].[promotions_ma_seq],'000'))) NOT NULL,
    CONSTRAINT [PK_promotions] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: vouchers
-- ------------------------------------------------------------
CREATE TABLE [vouchers] (
    [id] int IDENTITY(1,1) NOT NULL,
