    [discount_type] varchar(20) NOT NULL,
    [discount_value] decimal(18,2) NOT NULL,
    [min_order_value] decimal(18,2) DEFAULT ((0)) NULL,
    [max_discount] decimal(18,2) NULL,
    [start_date] datetime NOT NULL,
    [end_date] datetime NOT NULL,
    [usage_limit] int DEFAULT ((100)) NULL,
    [used_count] int DEFAULT ((0)) NULL,
    [is_public] bit DEFAULT ((1)) NULL,
    [customer_id] int NULL,
    [status] bit DEFAULT ((1)) NULL,
    CONSTRAINT [PK_vouchers] PRIMARY KEY CLUSTERED ([id])
);
GO
