    CONSTRAINT [PK_promotion_details] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: orders
-- ------------------------------------------------------------
CREATE TABLE [orders] (
    [id] int IDENTITY(1,1) NOT NULL,
    [order_code] varchar(50) NOT NULL,
    [customer_id] int NULL,
    [employee_id] int NULL,
    [order_type] varchar(20) NOT NULL,
    [status] varchar(50) NOT NULL,
    [total_amount] decimal(18,2) NOT NULL,
    [discount_amount] decimal(18,2) DEFAULT ((0)) NULL,
    [final_amount] decimal(18,2) NOT NULL,
    [payment_method] varchar(50) NULL,
    [shipping_address] nvarchar(255) NULL,
    [phone_number] nvarchar(20) NULL,
    [voucher_id] int NULL,
    [created_at] datetime DEFAULT (getdate()) NULL,
    [updated_at] datetime DEFAULT (getdate()) NULL,
    [receiver_name] nvarchar(100) NULL,
    [email] nvarchar(100) NULL,
    [payment_status] varchar(50) DEFAULT ('UNPAID') NULL,
    [shipping_fee] decimal(18,2) DEFAULT ((0)) NULL,
    [da_tru_kho] bit DEFAULT ((0)) NOT NULL,
    [payment_reference] nvarchar(40) NULL,
    [tinh_thanh_id] int NULL,
    [ten_tinh_thanh] nvarchar(100) NULL,
    [du_kien_giao_tu] date NULL,
    [du_kien_giao_den] date NULL,
    [ngay_giao_thuc_te] date NULL,
    [phuong_xa_id] int NULL,
    [ma_tinh_giao] nvarchar(2) NULL,
    [ma_phuong_giao] nvarchar(5) NULL,
    [ten_phuong_giao] nvarchar(100) NULL,
    [so_nha_duong] nvarchar(255) NULL,
    [dia_chi_giao_snapshot] nvarchar(600) NULL,
    [latitude] decimal(10,7) NULL,
    [longitude] decimal(10,7) NULL,
    [nguon_toa_do] nvarchar(20) NULL,
    [distance_km] decimal(12,2) NULL,
    [is_free_ship] bit NULL,
    [shipping_policy_version] int NULL,
    [shipping_note] nvarchar(255) NULL,
    [order_source] nvarchar(30) NULL,
    [sales_note] nvarchar(1000) NULL,
    [tien_mat] bigint DEFAULT ((0)) NOT NULL,
    [tien_chuyen_khoan] bigint DEFAULT ((0)) NOT NULL,
    [ghi_chu_thanh_toan] nvarchar(500) NULL,
    CONSTRAINT [PK_orders] PRIMARY KEY CLUSTERED ([id])
);
GO
-- ------------------------------------------------------------
-- Table: order_details
-- ------------------------------------------------------------
CREATE TABLE [order_details] (
    [id] int IDENTITY(1,1) NOT NULL,
    [order_id] int NULL,
    [product_variant_id] int NULL,
