-- Data: chatbot_faq (9 rows)
SET IDENTITY_INSERT [chatbot_faq] ON;
INSERT INTO [chatbot_faq] ([id], [ma], [cau_hoi], [tu_khoa], [tra_loi], [hien_thi], [doi_tuong]) VALUES
(1, N'KB001', N'Chính sách đổi trả hàng như thế nào?', N'đổi trả, doi tra, hoàn tiền, hoan tien, trả hàng, tra hang, bảo hành, bao hanh', N'F6S Store hỗ trợ đổi trả trong vòng 7 ngày kể từ khi nhận hàng với điều kiện giày còn nguyên tem mác, hộp và chưa qua sử dụng.', 1, N'KHACH'),
(2, N'KB002', N'Thời gian và chính sách giao hàng ra sao?', N'giao hàng, giao hang, vận chuyển, van chuyen, ship, phí ship, phi ship, bao lâu nhận', N'F6S Store giao hàng toàn quốc qua các đơn vị vận chuyển uy tín. Thời gian giao từ 2-4 ngày làm việc. Phí vận chuyển do bên thứ ba thu theo biểu phí thực tế.', 1, N'KHACH'),
(3, N'KB003', N'Cửa hàng hỗ trợ những phương thức thanh toán nào?', N'thanh toán, thanh toan, cod, chuyển khoản, chuyen khoan, quét mã, qr, tiền mặt, tien mat', N'Cửa hàng hỗ trợ thanh toán khi nhận hàng (COD), chuyển khoản ngân hàng qua VietQR tự động, và thanh toán tiền mặt/kết hợp trực tiếp tại quầy.', 1, N'KHACH'),
(4, N'KB004', N'Chính sách bảo mật thông tin khách hàng?', N'bảo mật, bao mat, thông tin, thong tin, quyền riêng tư, quyen rieng tu', N'Chúng tôi cam kết bảo mật thông tin cá nhân của bạn. Dữ liệu chỉ dùng để xử lý đơn hàng và liên hệ hỗ trợ khi cần thiết.', 1, N'KHACH'),
(5, N'KB005', N'Làm thế nào để đặt mua hàng trực tuyến?', N'mua hàng, mua hang, đặt hàng, dat hang, cách mua, cach mua, hướng dẫn, huong dan', N'Bạn chỉ cần chọn sản phẩm ưng ý, chọn size và màu sắc, bấm Thêm vào giỏ và tiến hành Đặt hàng tại trang thanh toán.', 1, N'KHACH'),
(6, N'KB_ADMIN_01', N'Hướng dẫn thao tác bán hàng tại quầy (POS)', N'pos, ban hang tai quay, tao don pos, hoa don cho, que the, quet ma, vietqr, giao hang pos', N'Để bán hàng tại quầy: 1) Truy cập menu Bán hàng tại quầy (/admin/pos); 2) Chọn hóa đơn chờ hoặc tạo mới (tối đa 5 hóa đơn chờ); 3) Chọn khách hàng hoặc dùng Khách lẻ mặc định; 4) Bấm nút "Thêm sản phẩm" (+) để chọn giày và số lượng (tồn kho giảm ngay); 5) Chọn phương thức thanh toán: Tiền mặt, Chuyển khoản (VietQR tự động) hoặc gạt công tắc "Giao hàng" nếu khách muốn ship hàng online; 6) Bấm Hoàn tất đơn hàng.', 1, N'NOI_BO'),
(7, N'KB_ADMIN_02', N'Hướng dẫn xử lý đơn hàng và hóa đơn', N'don hang, hoa don, xu ly don, xac nhan don, in hoa don, giao hang, huy don, invoices', N'Để quản lý đơn hàng: 1) Vào menu Quản lý hóa đơn (/admin/invoices); 2) Sử dụng các tab trạng thái (Chờ xử lý, Đã xác nhận, Đang chuẩn bị, Đang giao, Đã giao, Đã hủy) hoặc thanh lọc từ khóa/kênh bán; 3) Bấm "Xem chi tiết" để xem hóa đơn; 4) Tiến hành "Xác nhận đơn", chuyển trạng thái hoặc bấm "In hóa đơn" để in phiếu giao hàng cho khách.', 1, N'NOI_BO'),
(8, N'KB_ADMIN_03', N'Hướng dẫn kiểm tra tồn kho và nhập hàng', N'nhap hang, ton kho, kiem kho, dieu chinh ton, kho, inventory, bao ton', N'Để kiểm tra và cập nhật tồn kho: 1) Truy cập Quản lý tồn kho (/admin/inventory); 2) Lọc theo thương hiệu, kích cỡ, màu sắc hoặc tìm theo mã sản phẩm/biến thể; 3) Bấm "Điều chỉnh tồn" để tăng/giảm số lượng thực tế kèm ghi chú lý do (Nhập hàng mới, Kiểm kê định kỳ, Hàng lỗi/xuất hủy); 4) Mọi lịch sử biến động đều được lưu vết trong Lịch sử kho.', 1, N'NOI_BO'),
(9, N'KB_ADMIN_04', N'Hướng dẫn xử lý phiếu hỗ trợ khách hàng', N'phieu ho tro, ho tro khach, support ticket, tra loi khach, khach can gap', N'Để tiếp nhận và phản hồi phiếu hỗ trợ: 1) Vào menu Hỗ trợ > Phiếu hỗ trợ (/admin/support-tickets); 2) Lọc các phiếu trạng thái "Mới"; 3) Bấm "Xem chi tiết" để đọc nội dung và trích đoạn 10 tin nhắn gần nhất của khách với Chatbot; 4) Nhập nội dung giải đáp vào ô "Phản hồi" và bấm Gửi (hệ thống tự động gửi email thông báo cho khách nếu có email, hoặc ghi chú liên hệ SĐT).', 1, N'NOI_BO');
SET IDENTITY_INSERT [chatbot_faq] OFF;
GO
